const $=s=>document.querySelector(s), app=$('#app'),dialog=$('#lesson');
let state=JSON.parse(localStorage.getItem('grove-progress')||'{"xp":0,"done":{},"days":[]}'),cat='All topics',search='',view='home',quiz=null;
const cats=['All topics','Foundations','Present & past','Future forms','Conditionals','Language tools'];const colors=['#edf1df','#fcebdc','#e9e9f7','#e1eff2','#f8edce'];const symbols=['Aa','◷','↗','⑂','✧'];const modes=['Mixed quest','Multiple choice','Fill in the gaps','Spot the mistake','Unscramble','Matching','Conversation'];
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}function save(){localStorage.setItem('grove-progress',JSON.stringify(state));$('#xp').textContent='✦ '+state.xp+' XP'}
function art(){return `<svg class="art" role="img" aria-label="Illustration of a growing grammar garden with books, a pencil and a smiling sun" viewBox="0 0 440 280"><circle cx="235" cy="142" r="114" fill="#dce7c8"/><path d="M55 237Q220 205 393 237" fill="none" stroke="#bacb9f" stroke-width="2"/><g transform="translate(105 86) rotate(-12)"><rect x="0" y="10" width="95" height="132" rx="7" fill="#779263"/><path d="M13 10v132" stroke="#4d6d44" stroke-width="2"/><rect x="27" y="37" width="48" height="47" rx="3" fill="#e8efd9"/><text x="51" y="69" text-anchor="middle" fill="#4c6d3f" font-size="27" font-family="Georgia">Aa</text><path d="M26 108h46m-46 9h31" stroke="#bccfa6" stroke-width="3"/></g><g transform="translate(186 154) rotate(8)"><path d="M0 0q40-14 75 0q37-14 77 0v67q-40-12-77 0q-35-12-75 0z" fill="#fffcf0" stroke="#c9cdb2" stroke-width="2"/><path d="M75 0v67" stroke="#d2d5bd"/><path d="M14 15h43m-43 11h43m-43 11h30m46-22h43m-43 11h43m-43 11h28" stroke="#cbd6b8" stroke-width="3"/></g><g transform="translate(311 44)"><circle cx="0" cy="0" r="26" fill="#efc66e"/><path d="M-10 4q10 11 20 0" fill="none" stroke="#946d37" stroke-width="2" stroke-linecap="round"/><circle cx="-9" cy="-4" r="2" fill="#946d37"/><circle cx="9" cy="-4" r="2" fill="#946d37"/><path d="M0-41v-8m0 90v8m41-49h8m-90 0h-8m19-29-6-6m64 64 6 6m-6-64 6-6" stroke="#dbb45f" stroke-width="3" stroke-linecap="round"/></g><path d="M270 153q-2-40-24-70m16 42q-48-6-39-35q31-2 39 35m0-5q40-5 35-34q-31 2-35 34" fill="#83a36b"/><path d="m341 177 28-83 10 4-28 83-10 13z" fill="#e8b27d"/><path d="m341 177 10 4-10 13z" fill="#fff4dd"/><path d="m341 194 3-9 3 2z" fill="#5a6d4b"/><g fill="#fffaf0" stroke="#c5d4af"><path d="m69 82 4-11 4 11 11 4-11 4-4 11-4-11-11-4z"/><path d="m354 217 3-8 3 8 8 3-8 3-3 8-3-8-8-3z"/></g><rect x="73" y="199" width="71" height="30" rx="15" fill="#f5e6c4"/><text x="108" y="219" font-family="sans-serif" font-size="12" fill="#8e793d" text-anchor="middle">+20 XP ✧</text></svg>`}
function cards(){const list=TOPICS.filter(t=>(cat==='All topics'||t.cat===cat)&&t.title.toLowerCase().includes(search.toLowerCase())&&($('#level').value==='All levels'||t.level===$('#level').value));$('#topiccount').textContent=`${list.length} topics to explore`;$('#topics').innerHTML=list.map(t=>{let i=cats.indexOf(t.cat)-1;return `<article class="topic"><div class="symbol" style="background:${colors[i]}">${symbols[i]}</div><span class="level">${t.level}</span><div class="tag" style="margin-top:17px">${t.cat.toUpperCase()}</div><h3 style="margin-top:5px">${esc(t.title)}</h3><p>${esc(t.explain.split('. ')[0])}.</p><div class="meta"><span>${state.done[t.id]?'✓ Quest completed':t.bank.length+' examples · 6 activity types'}</span><button data-topic="${t.id}">Explore topic ↗</button></div></article>`}).join('')||'<div class="empty">No topics found. Try another search.</div>';document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>guide(+b.dataset.topic))}
function guide(id){let t=TOPICS[id];$('#lessoncontent').innerHTML=`<div class="eyebrow">${t.cat} · ${t.level}</div><h1>${esc(t.title)}</h1><p class="sub">Understand it. Then make it yours.</p><div class="guide"><b>How it works</b><p>${esc(t.explain)}</p><div class="formula">${esc(t.formula)}</div><p class="example">“${esc(t.sentence)}”</p></div><h3>A common mix-up</h3><p><s>${esc(t.error)}</s><br><b>✓ ${esc(t.sentence)}</b></p><p class="sub">Notice the form and word order before you begin.</p><div class="controls"><button class="primary" id="goquest">Start topic quest →</button><button class="secondary" id="goback">Keep exploring</button></div>`;$('#goquest').onclick=()=>start(id);$('#goback').onclick=()=>dialog.close();if(!dialog.open)dialog.showModal()}
function practice(){app.innerHTML=`<div class="eyebrow">THE PRACTICE PATCH</div><h1>Pick your kind of challenge.</h1><p class="sub">Choose a format and a topic. Every answer comes with a little insight.</p><div class="panel"><label for="practicetopic">Your topic</label><select id="practicetopic">${TOPICS.map(t=>`<option value="${t.id}">${t.title}</option>`)}</select><div class="modegrid">${modes.map((m,i)=>`<button data-mode="${i}"><span>${['⚡','◉','✎','⌕','▤','⇄','☏'][i]}</span>${m}</button>`).join('')}</div></div><div class="notice">Mixed quests combine six activity formats. Focused formats give you five different questions; matching gives you four sets of three sentence halves. Each topic has 13 model sentences, and new sets rotate through the bank. Conversation prompts include a partner speaking extension.</div>`;document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>start(+$('#practicetopic').value,+b.dataset.mode))}
function shuffled(values){let a=[...values];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function chooseItems(id,count){let bank=TOPICS[id].bank,rotation=JSON.parse(localStorage.getItem('grove-question-rotation')||'{}'),queue=(rotation[id]||[]).filter(key=>bank.some(x=>x.key===key)),selected=[];while(selected.length<count){if(!queue.length)queue=shuffled(bank.map(x=>x.key).filter(key=>!selected.includes(key)));let key=queue.shift();if(!selected.includes(key))selected.push(key)}rotation[id]=queue;localStorage.setItem('grove-question-rotation',JSON.stringify(rotation));return selected}
function currentItem(q){let key=q.itemKeys[q.mode===5?q.step*3:q.step];return {...TOPICS[q.id],...TOPICS[q.id].bank.find(x=>x.key===key)}}
function sentenceHalves(sentence){let words=sentence.split(' '),cut=Math.max(1,Math.floor(words.length/2));return [words.slice(0,cut).join(' '),words.slice(cut).join(' ')]}
function start(id,mode=0){let order=mode?Array(mode===5?4:5).fill(mode-1):[0,1,2,3,4,5];quiz={id,mode,step:0,answers:[],tokens:[],checked:false,score:0,order,itemKeys:chooseItems(id,mode===5?12:mode?5:8)};showq();if(!dialog.open)dialog.showModal()}
function showq(){let q=quiz,t=currentItem(q),kind=q.order[q.step];q.checked=false;q.choice=null;q.tokens=[];let words=t.sentence.replace(/[.?]$/,'').split(' ');q.wordbank=words.map((w,i)=>({w,i})).sort(()=>Math.random()-.5);$('#lessoncontent').innerHTML=`<div class="eyebrow">${esc(t.title)} · PRACTICE QUEST</div><div class="quizbar"><div style="width:${q.step/q.order.length*100}%"></div></div><span class="count">CHALLENGE ${q.step+1} OF ${q.order.length} · ${modes[kind+1].toUpperCase()}</span><div id="question"></div><div id="result" aria-live="polite"></div><div class="controls"><button class="primary" id="check">Check answer</button><button class="secondary" id="hint">Show grammar guide</button></div>`;
let c=$('#question');if(kind===0){c.innerHTML=`<p class="prompt">${esc(t.gap)}</p><div class="options">${[t.answer,t.wrong].sort(()=>Math.random()-.5).map(a=>`<button class="option" data-choice="${esc(a)}">${esc(a)}</button>`).join('')}</div>`}
if(kind===1)c.innerHTML=`<p class="sub" style="margin-top:22px">Complete the gap with the correct form.</p><p class="prompt">${esc(t.gap)}</p><input class="answer" id="typed" aria-label="Your answer" autocomplete="off" placeholder="Type the missing word or words…">`;
if(kind===2)c.innerHTML=`<p class="sub" style="margin-top:22px">Rewrite the sentence correctly.</p><p class="prompt">${esc(t.error)}</p><input class="answer" id="typed" aria-label="Corrected sentence" autocomplete="off" placeholder="Write the corrected sentence…">`;
if(kind===3)c.innerHTML=`<p class="prompt">Build a correct sentence.</p><p class="sub">Tap the words in order. Tap a selected word to return it.</p><div class="tokens" id="built" aria-label="Your sentence"></div><div class="tokens" id="bank"></div>`;
if(kind===4){q.matchKeys=q.mode===5?q.itemKeys.slice(q.step*3,q.step*3+3):[t.key,...q.itemKeys.slice(6,8)];let pairs=q.matchKeys.map(key=>sentenceHalves(TOPICS[q.id].bank.find(x=>x.key===key).sentence));q.match=pairs.map(pair=>pair[1]);let options=shuffled(q.match);c.innerHTML=`<p class="prompt">Match the sentence halves.</p><p class="sub">Match each beginning to its original ending, using the reference sentences.</p><details class="guide"><summary>Reference sentences</summary>${q.matchKeys.map(key=>`<p>${esc(TOPICS[q.id].bank.find(x=>x.key===key).sentence)}</p>`).join('')}</details>${pairs.map((pair,i)=>`<label class="matchrow"><span>${esc(pair[0])} …</span><select data-match="${i}"><option value="">Choose the ending…</option>${options.map(o=>`<option>${esc(o)}</option>`).join('')}</select></label>`).join('')}`}
if(kind===5)c.innerHTML=`<p class="sub" style="margin-top:22px">Message check · choose the correct version to send.</p><div class="guide"><b>Alex:</b> “Could you check my English before I send this message?”</div><p class="prompt">Your reply:</p><div class="options">${[t.sentence,t.error].sort(()=>Math.random()-.5).map(a=>`<button class="option" data-choice="${esc(a)}">${esc(a)}</button>`).join('')}</div><p class="sub">Partner extension: reply to the message, then write a new one using the same grammar.</p>`;
document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(q.checked)return;q.choice=b.dataset.choice;document.querySelectorAll('[data-choice]').forEach(x=>x.classList.toggle('selected',x===b))});if(kind===3)drawWords();$('#check').onclick=check;$('#hint').onclick=()=>{let r=$('#result');r.innerHTML=`<div class="guide">${esc(t.explain)}<div class="formula">${esc(t.formula)}</div></div>`};$('#typed')?.addEventListener('keydown',e=>{if(e.key==='Enter')check()})}
function drawWords(){let q=quiz;$('#built').innerHTML=q.tokens.map(i=>`<button class="token" data-remove="${i}">${esc(q.wordbank.find(w=>w.i===i).w)}</button>`).join('');$('#bank').innerHTML=q.wordbank.filter(w=>!q.tokens.includes(w.i)).map(w=>`<button class="token" data-word="${w.i}">${esc(w.w)}</button>`).join('');document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{if(!q.checked){q.tokens.push(+b.dataset.word);drawWords()}});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{if(!q.checked){q.tokens=q.tokens.filter(x=>x!==+b.dataset.remove);drawWords()}})}
const norm=s=>String(s).toLowerCase().replace(/[’‘]/g,"'").replace(/[.,!?]/g,'').replace(/\s+/g,' ').trim();
function check(){let q=quiz;if(q.checked)return;let t=currentItem(q),kind=q.order[q.step],answer=kind===3?q.tokens.map(i=>q.wordbank.find(w=>w.i===i).w).join(' '):kind===4?[...document.querySelectorAll('[data-match]')].map(s=>s.value):$('#typed')?.value||q.choice;if(!answer||(Array.isArray(answer)&&answer.includes(''))){toast('Give it a try first.');return}let correct=kind===4?answer.every((v,i)=>v===q.match[i]):norm(answer)===norm([0,1].includes(kind)?t.answer:t.sentence);q.checked=true;q.answers.push({kind,answer,itemKey:t.key,...(kind===4?{matchKeys:q.matchKeys}:{})});if(correct)q.score++;$('#result').innerHTML=`<div class="feedback ${correct?'':'bad'}"><b>${correct?'✦ That’s it! A little win.':'Keep growing — here’s the answer.'}</b>${esc(kind===4?'Correct endings: '+q.match.join(' / '):[0,1].includes(kind)?t.answer:t.sentence)}<p>${esc(t.explain)}</p></div>`;$('#check').textContent=q.step+1===q.order.length?'Finish quest →':'Next challenge →';$('#check').onclick=()=>{q.step++;if(q.step===q.order.length)finish();else showq()}}
function finish(){let q=quiz,t=TOPICS[q.id],reward=q.score*10,first=!(q.id in state.done);if(q.mode===0){state.done[q.id]=Math.max(state.done[q.id]||0,q.score);state.xp+=first?reward:Math.min(reward,10)}else{state.xp+=Math.min(reward,10)}let d=new Date().toLocaleDateString('en-CA');if(!state.days.includes(d))state.days.push(d);save();$('#lessoncontent').innerHTML=`<div class="eyebrow">A LITTLE MORE CONFIDENT</div><h1>Look at you grow. 🌱</h1><div class="bigscore">${q.score}<span style="font-size:25px;color:#8b9b80"> / ${q.order.length}</span></div><p>You completed ${esc(t.title)}.</p><p class="sub">Try again for a new mix of sentences from this topic’s 13-example bank.</p><p class="notice">Your practice progress is saved in this browser.</p><div class="controls"><button class="primary" id="again">Practise again</button><button class="secondary" id="finishclose">Back to my learning</button></div>`;$('#again').onclick=()=>start(q.id,q.mode);$('#finishclose').onclick=()=>{dialog.close();navigate(view)}}
function progress(){app.innerHTML=`<div class="eyebrow">YOUR GROWING SKILLS</div><h1>Every little win adds up.</h1><p class="sub">Your practice on this device. Keep exploring, one little win at a time.</p><div class="panel"><h2>${state.xp} XP · ${Object.keys(state.done).length} completed topics</h2>${TOPICS.filter(t=>t.id in state.done).map(t=>`<div class="progressrow"><span>${esc(t.title)}</span><b>${state.done[t.id]}/6 ✓</b></div>`).join('')||'<p class="sub">Your first quest is waiting. Pick a topic and start growing.</p>'}</div><div class="panel"><h3>Your milestones</h3><div class="controls"><span class="badge">${Object.keys(state.done).length?'✓':'○'} First sprout · 1 quest</span><span class="badge">${Object.keys(state.done).length>=5?'✓':'○'} Growing strong · 5 quests</span><span class="badge">${state.xp>=500?'✓':'○'} Grammar gardener · 500 XP</span></div></div>`}
let feedFilter='For you',feedLimit=6,reelIndex=0;const savedTopics=()=>JSON.parse(localStorage.getItem('grove-saved')||'[]');
function navigate(v){view=v;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));dialog.classList.remove('reel-dialog');if(v==='home')home();if(v==='library')library();if(v==='reels'){if(!app.innerHTML)home();openReel(0)}if(v==='practice')practice();if(v==='progress')progress();window.scrollTo({top:0,behavior:'smooth'})}
function home(){let list=TOPICS.filter(t=>(cat==='All topics'||t.cat===cat)&&(feedFilter!=='Saved'||savedTopics().includes(t.id)));let icons=['✦','Aa','◷','↗','⑂','✧'];app.innerHTML=`<div class="social-top"><div><h1>Your grammar era starts here<span style="color:#e05aa3">.</span></h1><p class="sub" style="margin:0">Fresh challenges. Little wins. A feed that helps you grow.</p></div><span class="spark">✧</span></div><div class="social-layout"><div class="feed-column"><div class="stories" aria-label="Topic categories">${cats.map((c,i)=>`<button class="story ${cat===c?'active':''}" data-story="${i}"><span class="story-ring"><span>${icons[i]}</span></span>${['Your mix','Foundations','Present & past','Future forms','Conditionals','Language tools'][i]}</button>`).join('')}</div><div class="feedtabs"><button data-feed="For you" class="${feedFilter==='For you'?'selected':''}">For you</button><button data-feed="Saved" class="${feedFilter==='Saved'?'selected':''}">Saved</button><button id="feed-reels">Reels ↗</button></div>${list.slice(0,feedLimit).map((t,i)=>feedPost(t,i)).join('')||'<div class="panel empty">Your saved collection starts here. Tap the bookmark on any challenge.</div>'}${list.length>feedLimit?'<button class="secondary" id="more-feed" style="width:100%">More for your feed ↓</button>':''}</div><div class="social-rail"><section class="rail-panel"><div class="profile-line"><div class="profile-pic">✦</div><div><b>Your daily grammar boost</b><small>CHOOSE A TOPIC. START A CHALLENGE.</small></div></div><div class="mini-stat"><span>✦ ${state.xp} XP earned</span><strong>${Object.keys(state.done).length} topics explored</strong></div><p>Jump straight into 33 topics and 429 examples. Your progress stays in this browser.</p><button class="primary" id="rail-practice">Open practice studio →</button><button class="pink-link" id="rail-topics">Explore all topics ↗</button></section><section class="rail-panel"><h3>On your radar <span style="float:right;color:#ce8fc5">↗</span></h3>${[7,14,23].map((id,i)=>`<div class="rail-trend"><span class="trend-num">0${i+1}</span><button data-trend="${id}"><b>${esc(TOPICS[id].title)}</b><small>${TOPICS[id].level} · 13 examples · 6 formats</small></button></div>`).join('')}</section><section class="rail-panel quote-panel"><span style="color:#bd83c5;font-size:26px">✳</span><h3>Make mistakes.<br>Make progress.<br>Make it yours.</h3><p>THAT’S THE WHOLE IDEA.</p></section><div class="rail-foot">A learning space, with a social twist.<br>Just you and your next little win.<br>Grammar Grove · Stay curious ✧</div></div></div>`;
document.querySelectorAll('[data-story]').forEach(b=>b.onclick=()=>{cat=cats[+b.dataset.story];feedLimit=6;home()});document.querySelectorAll('[data-feed]').forEach(b=>b.onclick=()=>{feedFilter=b.dataset.feed;home()});document.querySelectorAll('[data-post-start]').forEach(b=>b.onclick=()=>start(+b.dataset.postStart));document.querySelectorAll('[data-post-guide]').forEach(b=>b.onclick=()=>guide(+b.dataset.postGuide));document.querySelectorAll('[data-bookmark]').forEach(b=>b.onclick=()=>{let saved=savedTopics(),id=+b.dataset.bookmark;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];localStorage.setItem('grove-saved',JSON.stringify(saved));b.classList.toggle('saved',saved.includes(id));b.setAttribute('aria-pressed',saved.includes(id));toast(saved.includes(id)?'Saved to your collection.':'Removed from saved.');if(feedFilter==='Saved')home()});document.querySelectorAll('[data-trend]').forEach(b=>b.onclick=()=>guide(+b.dataset.trend));$('#feed-reels').onclick=()=>navigate('reels');$('#rail-practice').onclick=()=>navigate('practice');$('#rail-topics').onclick=()=>navigate('library');$('#more-feed')?.addEventListener('click',()=>{feedLimit+=6;let y=scrollY;home();scrollTo(0,y)})}
function feedPost(t,i){const title=t.title.replace(' & ',' + ');return `<article class="feed-post"><div class="post-head"><div class="post-avatar">${symbols[cats.indexOf(t.cat)-1]}</div><div><b>grammar.grove <span class="verified">✹</span></b><small>${esc(t.cat)} · A little learning break</small></div><span class="level-pill">${t.level}</span></div><div class="post-art art-${i%4}"><span class="overline">IN YOUR LEARNING ERA</span><span class="floating-pill">✦ tiny challenge, big energy</span><h2>${esc(title)}<span style="color:#ac70bc">.</span></h2><p>${esc(t.explain.split('. ')[0])}.</p><span class="floating-icon" aria-hidden="true">${['Aa','?!','↗','if'][i%4]}</span><span class="corner-star" aria-hidden="true">✧</span></div><div class="post-actions"><button class="iconbutton" data-post-start="${t.id}" aria-label="Start ${esc(t.title)} challenge">▷</button><button class="iconbutton" data-post-guide="${t.id}" aria-label="Read grammar explanation">☷</button><button class="iconbutton bookmark ${savedTopics().includes(t.id)?'saved':''}" data-bookmark="${t.id}" aria-label="Save ${esc(t.title)}" aria-pressed="${savedTopics().includes(t.id)}">♧</button></div><div class="post-caption"><b>grammar.grove</b> ${['A little practice for your next big “I get it.”','Your next confidence boost is one challenge away.','Grammar that sticks. One little win at a time.'][i%3]}<span class="hashtags">#${t.title.toLowerCase().replace(/[^a-z]/g,'')} #learnatyourpace #${t.level}</span><button class="post-cta" data-post-start="${t.id}"><span>Take the challenge · fresh sentence mix</span><span>Let’s go ↗</span></button></div></article>`}
function library(){app.innerHTML=`<div class="eyebrow">EXPLORE YOUR INTERESTS</div><h1>Find your next obsession.</h1><p class="sub">All 33 topics. Clear guides. Plenty of little wins.</p><div class="section-top"><input class="search" aria-label="Search grammar topics" placeholder="Search grammar…" value="${esc(search)}"><label>Level <select id="level"><option>All levels</option><option>A1</option><option>A2</option><option>B1</option></select></label></div><div class="tabs">${cats.map(c=>`<button data-cat="${c}" class="${cat===c?'selected':''}">${c}</button>`).join('')}</div><p class="count" id="topiccount"></p><div class="grid" id="topics"></div>`;$('.search').oninput=e=>{search=e.target.value;cards()};$('#level').onchange=cards;document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{cat=b.dataset.cat;library()});cards()}
function openReel(index){reelIndex=(index+TOPICS.length)%TOPICS.length;let t=TOPICS[reelIndex];dialog.classList.add('reel-dialog');$('#lessoncontent').innerHTML=`<div class="reel-stage"><div class="reel-top"><span>GRAMMAR REELS</span><b>For you</b><span>${reelIndex+1} / ${TOPICS.length}</span></div><div><div class="eyebrow">${esc(t.cat)} · ${t.level}</div><h2>${esc(t.title)}<span style="color:#fa75b8">.</span></h2><div style="font:500 23px/1.45 Outfit;color:#ffe1f2">${esc(t.gap)}</div><p>${esc(t.explain.split('. ')[0])}.</p><button class="primary" id="reel-start">Try this challenge ↗</button></div><div class="reel-bottom"><b>@grammar.grove ✹</b><p>Scroll into your next skill. #${t.level} #grammar</p><div class="controls"><button class="secondary" id="reel-prev" aria-label="Previous reel">↑ Previous</button><button class="secondary" id="reel-guide">Read guide</button><button class="secondary" id="reel-next" aria-label="Next reel">Next ↓</button></div></div></div>`;$('#reel-start').onclick=()=>{dialog.classList.remove('reel-dialog');start(t.id)};$('#reel-guide').onclick=()=>{dialog.classList.remove('reel-dialog');guide(t.id)};$('#reel-prev').onclick=()=>openReel(reelIndex-1);$('#reel-next').onclick=()=>openReel(reelIndex+1);let y;$('.reel-stage').ontouchstart=e=>y=e.touches[0].clientY;$('.reel-stage').ontouchend=e=>{let dy=e.changedTouches[0].clientY-y;if(Math.abs(dy)>65)openReel(reelIndex+(dy<0?1:-1))};if(!dialog.open)dialog.showModal()}
dialog.addEventListener('keydown',e=>{if(dialog.classList.contains('reel-dialog')&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();openReel(reelIndex+(e.key==='ArrowDown'?1:-1))}});dialog.addEventListener('close',()=>dialog.classList.remove('reel-dialog'));
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$('.close').onclick=()=>dialog.close();$('#classmode').onclick=()=>{document.body.classList.toggle('classmode');toast(document.body.classList.contains('classmode')?'Classroom display enabled':'Classroom display off')};save();navigate('home');
